using System.Text.Json;
namespace ONEXTweaks.WidgetBridge;
internal static class ControllerOemGestureVerification
{
 internal static async Task<int> Model(string file)
 {
  int checks=0;void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException(message);}
  try
  {
   foreach(string button in ControllerOemPolicy.Inputs)foreach(int window in new[]{100,150,300,600})
   {
    var policy=new ControllerOemPolicy(DoublePresses:new(){{button,new(true,window,new("gamepad","B"))}}).Validate();var engine=new ControllerOemGestureState();engine.Update(policy,true,0);
    Check(engine.Feed(new(button,true),10).Length==0,"Double enabled must not dispatch first down");Check(engine.Feed(new(button,true),11).Length==0,"Duplicate down must be ignored");engine.Feed(new(button,false),30);Check(engine.Tick(29+window).Length==0,"Single fired before full release window");var single=engine.Tick(30+window);Check(single.Length==1&&single[0]==new ControllerOemSignal(button,true),"Single expiry dispatch wrong");Check(engine.Tick(109+window).Length==0,"Single pulse ended early");Check(engine.Tick(110+window).SequenceEqual(new[]{new ControllerOemSignal(button,false)})&&engine.Mask==0,"Single pulse did not release");
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);engine.Feed(new(button,false),30);var twice=engine.Feed(new(button,true),29+window);Check(twice.SequenceEqual(new[]{new ControllerOemSignal(button+":Double",true)})&&engine.LastGesture=="Double","Double not recognized before boundary");Check(engine.Tick(30+window).Length==0,"Single fired alongside double");Check(engine.Feed(new(button,false),40+window).Length==0&&engine.Mask!=0,"Short double pulse was lost between polling ticks");Check(engine.Tick(109+window).SequenceEqual(new[]{new ControllerOemSignal(button+":Double",false)})&&engine.Mask==0,"Double held output did not release after minimum pulse");
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);Check(engine.Tick(10+window).SequenceEqual(new[]{new ControllerOemSignal(button,true)}),"Long first hold did not become single");Check(engine.Feed(new(button,false),11+window).Length==0&&engine.Mask!=0,"Near-boundary single pulse too short for polling");Check(engine.Tick(90+window).SequenceEqual(new[]{new ControllerOemSignal(button,false)}),"Long single did not release");
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);engine.Feed(new(button,false),30);var exact=engine.Feed(new(button,true),30+window);Check(exact.Any(value=>value.Button==button&&value.Pressed)&&!exact.Any(value=>value.Button.EndsWith(":Double",StringComparison.Ordinal)),"Exact deadline must start a new click");engine.Cancel();
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);engine.Feed(new(button,false),30);Check(engine.Update(policy with{},true,40).Length==0&&engine.Tick(30+window).Length==0,"Profile replacement dispatched stale pending click");
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);engine.Feed(new(button,false),30);engine.Feed(new(button,true),40);var disabled=engine.Update(policy,false,50);Check(disabled.Length==1&&disabled[0].Cancelled&&!disabled[0].Pressed&&engine.Mask==0,"Off did not cancel held double");engine.Update(policy,true,60);Check(engine.Feed(new(button,true),70).Length==0,"Held source reactivated after enable");engine.Feed(new(button,false),80);Check(engine.Feed(new(button,true),90).Length==0&&engine.Tick(90+window).Any(value=>value.Pressed),"Fresh press did not rearm");
    engine=new();engine.Update(policy,true,0);engine.Feed(new(button,true),10);engine.Feed(new(button,false),30);Check(engine.Tick(2000).Length==0&&engine.Mask==0,"Suspend gap fired an old click");
   }
   var queued=new ControllerOemGestureState();var queuedPolicy=new ControllerOemPolicy().Validate();queued.Update(queuedPolicy,true,0);queued.Reconfigure(queuedPolicy,true,1,new[]{"Home"});Check(queued.Feed(new("Home",true),2).Length==0&&queued.Mask==0,"Queued pre-transition down activated a new profile");queued.Feed(new("Home",false),3);Check(queued.Feed(new("Home",true),4).SequenceEqual(new[]{new ControllerOemSignal("Home",true)}),"Release did not rearm snapshot-held control");
   var immediatePolicy=new ControllerOemPolicy().Validate();var immediate=new ControllerOemGestureState();immediate.Update(immediatePolicy,true,0);Check(immediate.Feed(new("Home",true),1).SequenceEqual(new[]{new ControllerOemSignal("Home",true)})&&immediate.Feed(new("Home",false),2).SequenceEqual(new[]{new ControllerOemSignal("Home",false)}),"Legacy single gained a delay");
   var both=new ControllerOemPolicy(DoublePresses:new(){{"M1",new(true,300,new("gamepad","A"))},{"M2",new(true,150,new("gamepad","B"))}}).Validate();var parallel=new ControllerOemGestureState();parallel.Update(both,true,0);parallel.Feed(new("M1",true),10);parallel.Feed(new("M2",true),20);parallel.Feed(new("M1",false),30);parallel.Feed(new("M2",false),40);Check(parallel.Feed(new("M1",true),100).Single().Button=="M1:Double","Different button interfered with double");Check(parallel.Tick(190).Single().Button=="M2","Independent single window lost");
   var fast=new ControllerOemGestureState();fast.Update(both,true,0);fast.Feed(new("M1",true),1);fast.Feed(new("M1",false),5);fast.Feed(new("M1",true),10);fast.Feed(new("M1",false),15);fast.Feed(new("M1",true),20);fast.Feed(new("M1",false),25);fast.Feed(new("M1",true),30);fast.Feed(new("M1",false),35);Check(fast.Tick(90).Length==0&&fast.Mask!=0&&fast.Sequence==2,"Rapid double inherited a stale pulse expiry");Check(fast.Tick(110).Length==1&&fast.Mask==0,"Rapid double did not finally release");
   var p=new ControllerPolicy(Oem:both).Validate();var translator=new ControllerTranslator();Check(translator.Translate(new(Oem:(ushort)(1<<(6+4))),p).Pad.Buttons==4096,"Double mask did not reach virtual gamepad");Check(translator.Translate(new(Oem:(ushort)(1<<(6+5))),p).Pad.Buttons==8192,"Second double target lost");Check(translator.Translate(new(),p).Pad.Buttons==0,"Double target stuck after mask release");
   var reset=ControllerRemappingGroups.ResetBinding(p,"OEM:M1");var resetDoubles=reset.Oem?.DoublePresses;Check(resetDoubles!=null&&!resetDoubles.ContainsKey("M1")&&resetDoubles.ContainsKey("M2"),"Individual restore touched another double configuration");Check(ControllerRemappingGroups.ResetGroup(p,"oem").Oem!.DoublePresses==null,"OEM group restore kept double assignments");
   string legacy=JsonSerializer.Serialize(new ControllerOemPolicy().Validate(),Backend.Program.Json);Check(!legacy.Contains("doublePresses",StringComparison.Ordinal),"Legacy document gained a double field");foreach(int invalid in new[]{99,601}){bool rejected=false;try{new ControllerOemPolicy(DoublePresses:new(){{"M1",new(true,invalid)}}).Validate();}catch(InvalidDataException){rejected=true;}Check(rejected,"Unsafe window accepted");}
   await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=true,checks,modelOnly=true,physicalOwnerInputTested=false,hardwareWrites=0},Backend.Program.Json));return 0;
  }catch(Exception error){await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=false,checks,error=error.Message},Backend.Program.Json));return 2;}
 }
}
